mapper.select:
SELECT log.order_id,log.charging_flag,log.param,log.create_by,log.create_time,manage.interface_name,manage.interface_type,price FROM interface_log log LEFT JOIN interface_manage manage on log.interface_manage_no = manage.interface_manage_no where log.code = 200
and log.dept_id = #{deptId}
and log.create_time > #{startTime}
and log.create_time < #{endTime}
and log.create_by like concat('%',concat(#{userName}),'%')
GROUP BY log.order_id,log.id order by log.create_time desc

select log.create_time from interface_log log JOIN interface_manage manage on log.interface_manage_no = manage.interface_manage_no where TO_DAYS(log.create_time) = TO_DAYS(NOW()) and code = 200
and log.dept_id = #{deptId}
ORDER BY log.create_time DESC limit 1

select log.create_time from interface_log log JOIN interface_manage manage on log.interface_manage_no = manage.interface_manage_no where 1=1 and log.code = 200
and log.dept_id = #{deptId}
ORDER BY log.create_time DESC limit 1
